/* Departamento de Música · IES Infanta Elena — generador de actas en PDF (vista de impresión A4). Se carga solo al ver o descargar un acta. */
(function(){
var F={"r": "data:font/woff;base64,", "b": "data:font/woff;base64,", "i": "data:font/woff;base64,", "bi": "data:font/woff;base64,", "ab": "data:font/woff;base64,"},MEMB="data:image/jpeg;base64,";
var MESES=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function dmy(s){return s?s.split('-').reverse().join('/'):''}
function larga(s){if(!s)return '…';var d=new Date(s+'T12:00');return d.getDate()+' de '+MESES[d.getMonth()]+' de '+d.getFullYear()}
/* Texto del acta → bloques con palabras y estilos */
function toks(s,boldPre){var out=[],b=false,parts=String(s).split(/(\*\*)/);parts.forEach(function(p){if(p=='**'){b=!b;return}p.split(/\s+/).forEach(function(w){if(w)out.push({w:w,b:b})})});
 if(boldPre){var m=String(s).replace(/\*\*/g,'').match(/^([^:]{3,95}):\s/);if(m&&!/[.;]\s/.test(m[1])){var n=m[1].split(/\s+/).length;for(var i=0;i<n&&i<out.length;i++)out[i].b=true}}return out}
function parsea(texto){var L=String(texto||'').replace(/\r/g,'').split('\n'),B=[],cab=0;
 L.forEach(function(raw){var l=raw.replace(/^#+\s*/,'').trim();if(!l)return;var lim=l.replace(/\*\*/g,'');
  if(cab<4&&(/^ACTA\s+DE\s+(LA\s+)?REUNI/i.test(lim)||/^Acta\s*n[ºo°.]?\s*\d+/i.test(lim))){cab++;return}cab=9;
  if(/^(Fdo\.?|V[ºo°]\s*B[ºo°]|\(Jefe de Departamento\)\s*$)/i.test(lim))return;
  var ind=/^(\s{2,}|\t)/.test(raw),m;
  if(m=lim.match(/^(\d+\.\d+\.?)\s+(.*)$/)){B.push({k:/:\s/.test(m[2].slice(0,120))?'p':'h',t:toks('**'+m[1]+'** '+m[2],true)});return}
  if((m=lim.match(/^(\d+)\.\s+(.*)$/))&&lim.length<=140){B.push({k:'h',t:toks('**'+lim.replace(/\*\*/g,'')+'**')});return}
  if(m=l.match(/^[◦○▪]\s*(.*)$/)){B.push({k:'li2',t:toks(m[1],true)});return}
  if(m=l.match(/^[•\-\*·–]\s+(.*)$/)){B.push({k:ind?'li2':'li',t:toks(m[1],true)});return}
  if(m=lim.match(/^(\d+)\.\s+(.*)$/)){B.push({k:'num',n:m[1],t:toks(m[2],true)});return}
  B.push({k:'p',t:toks(l,false)})});return B}
function html(b,cont){var t=b.t.map(function(x){return x.b?'<b>'+esc(x.w)+'</b>':esc(x.w)}).join(' ').replace(/<\/b> <b>/g,' ');
 if(b.k=='h')return '<h4>'+t+'</h4>';if(b.k=='li'||b.k=='li2')return '<div class="'+b.k+(cont?' cont':'')+'">'+t+'</div>';if(b.k=='num')return '<div class="li2 numl'+(cont?' cont':'')+'" data-n="'+(cont?'':b.n+'.')+'">'+t+'</div>';
 if(b.k=='raw')return b.h;return '<p'+(cont?' class="cont"':'')+'>'+t+'</p>'}
var CSS=function(){return "@font-face{font-family:Cal;src:url("+F.r+") format('woff');font-weight:400;font-style:normal}@font-face{font-family:Cal;src:url("+F.b+") format('woff');font-weight:700;font-style:normal}@font-face{font-family:Cal;src:url("+F.i+") format('woff');font-weight:400;font-style:italic}@font-face{font-family:Cal;src:url("+F.bi+") format('woff');font-weight:700;font-style:italic}@font-face{font-family:Ari;src:url("+F.ab+") format('woff');font-weight:700}"+
 "@page{size:A4;margin:0}*{box-sizing:border-box}html,body{margin:0;background:#e8e4ec;-webkit-print-color-adjust:exact;print-color-adjust:exact}"+
 ".bar{position:sticky;top:0;z-index:5;display:flex;gap:12px;align-items:center;justify-content:center;flex-wrap:wrap;padding:10px;background:#3a1840;color:#fff;font:15px system-ui,sans-serif}.bar button{font:inherit;background:#fff;color:#3a1840;border:0;border-radius:9px;padding:8px 16px;cursor:pointer}.bar span{opacity:.85;font-size:13px}"+
 ".pg{width:210mm;height:297mm;background:#fff;position:relative;margin:8mm auto;box-shadow:0 2px 14px rgba(0,0,0,.18);overflow:hidden;break-after:page;page-break-after:always}.pg:last-child{break-after:auto;page-break-after:auto}"+
 ".mb{position:absolute;left:1.1mm;top:2.1mm;width:207.4mm}.ct{position:absolute;left:30mm;right:30mm;top:31mm;bottom:25mm;font:12pt/1.42 Cal,Calibri,Carlito,sans-serif;color:#000}.num{position:absolute;bottom:11mm;left:0;right:0;text-align:center;font:10pt Cal,sans-serif;color:#333}"+
 ".tit{font:700 12.3pt/1.4 Ari,Arial,sans-serif;text-align:center;margin:0}.tit2{font:700 12.3pt/1.4 Ari,Arial,sans-serif;text-align:center;margin:6pt 0 8pt;white-space:pre}"+
 "p{margin:0 0 9pt;text-align:justify}h4{font-weight:700;font-size:12pt;margin:12pt 0 9pt}.li,.li2{position:relative;text-align:justify;margin:0 0 7pt;padding-left:22pt}.li2{padding-left:44pt}.li:before{content:'•';position:absolute;left:8pt}.li2:before{content:'◦';position:absolute;left:30pt}.numl:before{content:attr(data-n);left:26pt}.cont:before{content:''!important}p.cont{text-indent:0}"+
 ".firmas{display:grid;grid-template-columns:1fr 1fr;gap:34pt 24pt;margin-top:46pt}.firmas div{line-height:1.5}.firmas div:last-child:nth-child(odd){grid-column:1/-1;justify-self:center;text-align:center}"+
 ".port{position:absolute;left:30mm;right:30mm;font-family:Cal,sans-serif}.dil h1{font:700 17pt Cal,sans-serif;text-align:center;margin:30mm 0 18mm}.dil p{line-height:1.6;margin-bottom:14pt}.dil .vb{display:grid;grid-template-columns:1fr 1fr;gap:10pt;margin-top:34mm}.dil .vb div{min-height:40mm;display:flex;flex-direction:column;justify-content:space-between}"+
 "@media print{html,body{background:#fff}.bar{display:none}.pg{margin:0;box-shadow:none}}#mide{position:absolute;left:-9999px;top:0;width:150mm;visibility:hidden}"};
var SCRIPT=function(){/* se ejecuta en la pestaña nueva */
 var D=window.__D,M=D.membrete,pages=[],root=document.getElementById('pp');
 function nueva(extra){var p=document.createElement('div');p.className='pg';p.innerHTML='<img class="mb" src="'+M+'" alt="">'+(extra||'<div class="ct"></div>')+'<div class="num"></div>';root.appendChild(p);pages.push(p);return p}
 function cabe(ct){return ct.scrollHeight<=ct.clientHeight+1}
 function pon(acta){var p=nueva(),ct=p.querySelector('.ct');ct.innerHTML=acta.cab;
  acta.bloques.forEach(function(b){var el=document.createElement('div');el.innerHTML=b.html0;var n=el.firstChild;ct.appendChild(n);if(cabe(ct))return;
   if(b.firmas){ct.removeChild(n);p=nueva();ct=p.querySelector('.ct');ct.appendChild(n);return}
   var tk=b.t,lo=0,hi=tk.length;ct.removeChild(n);
   while(lo<hi){var mid=Math.ceil((lo+hi)/2);var e2=document.createElement('div');e2.innerHTML=b.render(tk.slice(0,mid),false);var x=e2.firstChild;ct.appendChild(x);var ok=cabe(ct);ct.removeChild(x);if(ok)lo=mid;else hi=mid-1}
   if(lo>0&&lo<tk.length&&b.partible){var a=document.createElement('div');a.innerHTML=b.render(tk.slice(0,lo),false);ct.appendChild(a.firstChild)}else lo=0;
   var resto=tk.slice(lo);p=nueva();ct=p.querySelector('.ct');var r=document.createElement('div');r.innerHTML=b.render(resto,lo>0);ct.appendChild(r.firstChild)})}
 function bloques(a){return a.bloques.map(function(b){if(b.k=='firmas')return{firmas:1,html0:b.h};return{t:b.t,partible:b.k!='h',html0:window.__html(b,false),render:function(t,c){return window.__html({k:b.k,n:b.n,t:t},c)}}})}
 if(D.libro){var po=nueva('<div class="port" style="top:62mm;font-size:13pt">LIBRO DE ACTAS</div><div class="port" style="top:140mm;font-size:21pt;font-weight:700">DEPARTAMENTO DE MÚSICA</div><div class="port" style="top:228mm;font-size:21pt;font-weight:700">CURSO '+D.curso+'</div>');
  var dl=nueva('<div class="ct dil"><h1>Diligencia de apertura del libro de actas</h1><p>Diligencia de apertura del libro de actas del departamento de música IES Infanta Elena de Jumilla, provincia de Murcia, que se compone de <span class="tot"></span> páginas, selladas y numeradas correlativamente de la 1 a la <span class="tot"></span>, cuya primera anotación es el acta del departamento de '+D.dil.primera+', y la última es el acta del departamento de '+D.dil.ultima+'.</p>'+(D.dil.anterior?'<p>Este libro es continuación de otro con igual denominación, cuya última anotación fue el acta del departamento de '+D.dil.anterior+'.</p>':'')+'<p>Y para que así conste, firmo la presente en Jumilla.</p><div class="vb"><div><span>Vº Bº, LA DIRECTORA</span><span>Fdo: '+D.dil.directora+'</span></div><div><span>LA SECRETARIA DEL CENTRO,</span><span>Fdo: '+D.dil.secretaria+'</span></div></div></div>')}
 D.actas.forEach(function(a){a.bloques=bloques(a);pon(a)});
 if(D.numerar){pages.forEach(function(p,i){p.querySelector('.num').textContent=(i+1)});document.querySelectorAll('.tot').forEach(function(s){s.textContent=pages.length})}
 document.getElementById('npag').textContent=pages.length+(pages.length==1?' página':' páginas');document.body.setAttribute('data-listo','1')};
window.DMPDF={membrete:MEMB,larga:larga,
 abrir:function(o){/* o:{titulo,libro,curso,numerar,membrete,dil,actas:[{numero,fecha,hora,texto,firmas:[{nombre,jefe}]}]} */
  var actas=o.actas.map(function(a){var B=parsea(a.texto).map(function(b){return{k:b.k,n:b.n,t:b.t}});
   var f=a.firmas.map(function(x){return '<div>Fdo. '+esc(x.nombre)+(x.jefe?'<br>(Jefe de Departamento)':'')+'</div>'}).join('');B.push({k:'firmas',h:'<div class="firmas">'+f+'</div>'});
   return{cab:'<p class="tit">ACTA DE LA REUNIÓN DEL DEPARTAMENTO DE MÚSICA</p><p class="tit2">Acta nº'+esc(a.numero)+'     Fecha: '+dmy(a.fecha)+'     Hora: '+esc(a.hora||'')+'</p>',bloques:B}});
  var dil=o.dil?{primera:esc(larga(o.dil.primera)),ultima:esc(larga(o.dil.ultima)),anterior:o.dil.anterior?esc(larga(o.dil.anterior)):'',directora:esc(o.dil.directora||'…'),secretaria:esc(o.dil.secretaria||'…')}:null;
  var datos={membrete:o.membrete||MEMB,libro:!!o.libro,curso:esc(o.curso||''),numerar:!!o.numerar,dil:dil,actas:actas};
  var doc='<!doctype html><html lang="es"><head><meta charset="utf-8"><title>'+esc(o.titulo)+'</title><style>'+CSS()+'</style></head><body><div class="bar"><button onclick="window.print()">Descargar PDF</button><span>En la ventana de impresión elige «Guardar como PDF».</span><span id="npag"></span></div><div id="pp"></div>'+
   '<script>window.__D='+JSON.stringify(datos).replace(/</g,'\\u003c')+';window.__html='+html.toString().replace(/esc\(/g,'__esc(')+';function __esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;"}[c]})}'+
   'document.fonts.load("12pt Cal").then(function(){return document.fonts.load("bold 12pt Cal")}).then(function(){return document.fonts.ready}).then(function(){('+SCRIPT.toString()+')();'+(o.imprimir?'setTimeout(function(){window.print()},300);':'')+'});<\/script></body></html>';
  var w=o.ventana||window.open('','_blank');if(!w){alert('El navegador ha bloqueado la ventana nueva. Permite las ventanas emergentes para esta página.');return}
  w.document.open();w.document.write(doc);w.document.close();return w}};
})();
